BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (304::BIGINT, 'Meta con él. ¿Por qué? Explica bien, es dulce, sus evaluaciones son extremadamente fáciles, fomenta la participación, y la mayoría del curso lo lleva virtual. Es un verdadero GOAT. Si no puede conectarse a algunas clases, pero entrega todos los trabajos, él se lo perdona. (Las deja grabadas)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '84d736bd5cea9e53c7644f72a96567dcbbe33b90940b9119b32be0c3013d63b7'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Súper buen profe, es muy cómico, explica de forma muy accesible y sus evaluaciones son muy chill, básicamente trabajo cotidiano. Se presta para aprender realmente si usted lo quiere o para pasar sencillo si también es esa su prioridad.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, '136a863b200d7ca4f13c6a4acfcbb1e877bc551db01c9642fccaec8706a4ac85'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'La mayoría de las clases fueron virtuales, él es relajado y califica muy suave. Hace muchos trabajos cortos fáciles para practicar, las clases quedan grabadas y hace 2 proyectos sencillos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'b5e5e1de438277ab9bf8ad13ee1608e271bd8e22b6f33b576edf17fc205a176a'::TEXT, ARRAY[1030]::BIGINT[]),
    (304::BIGINT, 'No deja exámenes, las tareas y proyectos son fáciles, ayuda con todo, las clases de él son cómicas, explica muy bien y es muy paciente con los estudiantes, tiene vocación como profesor, lo recomiendo totalmente. Mientras usted asista a todas las clases y entregue todo, el curso se pasa!!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'a0615f2bf5c843c25db282a96183e646ac06f5efcef3a7e0ad74f202ed1b2988'::TEXT, ARRAY[1030]::BIGINT[]),
    (304::BIGINT, 'Explica muy bien, ayuda un monton. las clases quedan grabadas. El man es bien divertido. Meta con el, muy recomendado. Buen material extra para practicar. Dedica una clase a historia (perdida de tiempo a la que los otros profes le dedican semanas), se enfoca en programar. trabajos rapidos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '5e604e6f559cde8efc9f9f88590dc63afdade3bc755fd6f142c7b66a4a4ecd26'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Un muy buen profesor para llevar elementos. Cae muy bien, y los trabajos que deja son perfectamente manejables. Con los exámenes hay que ponerse más las pilas, pero igual son pasables. Lo recomiendo bastante!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-05-05T00:00:00+00:00'::TIMESTAMPTZ, 'ecb64965853313a3b85a7abaae5aa8b77b2aefb9956f19027a5118462d6f54fe'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Super sencillo de pasar mientras hagas los trabajos los cuales son fáciles y no muy largos lo pasas super bien, es un profe muy relax eso si tarda en calificar TODO.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'c3406025824b0f50d8fb333e3879c28c98e9d2b4a36dde553fd2c305b3690ae3'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Cae bien lo cual importa bastante. Parece como si por responsabilidades externas no le prestase tanta atención a su curso TEC; mandó un proyecto como con 1 mes de atraso y casi no dejó entregables. Muy fácil de pasar con él, tan fácil que uno ni sabe si aprendió lo que era jaja.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Pocos exámenes']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '465e2343b68d3c0f2bab79f05109c8970f76862fcd60665a407acdead65deba4'::TEXT, ARRAY[1030]::BIGINT[]),
    (304::BIGINT, 'El profe sabe bastante, es cómico y suele ayudar a los estudiantes. Literalmente él hace trabajos los cuales uno copia para posteriormente entregarlos, de ahí uno obtiene nota fácil. Lo difícil pueden ser los exámenes, califica bastante duro porque se fija mucho en los detalles, dura mucho revisand'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'ee9d5f8356df3d45db74cdc87b7e1fa77ed8892d0815b40710d3a59d9a163050'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Muy buen profesor, hace las clases dinámicas y siempre trata de dejar todo claro mientras resuelve los ejercicios. Solo hace dos exámenes, pero los revisa super tarde, puede que incluso le ponga 100 porque no le dio tiempo de revisar. Matricule con él si puede.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '368a68f861655d6ebf7276e0bd2dca746657853a36c89a8e31c7cbcca50a566b'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'muy buen profe, si una persona no tiene nada de conocimiento de programación con el le ayuda bastante, explica muy bien los conceptos, es fácil incluso si no tienes mucho interes en aprender a programar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '56e81b15d77d71359515c8237d0a57c74a55adff47bcc76de38a8020f6d910b9'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Buen profesor, clases interactivas y hasta explica otros temas que no vienen en el plan para reforzar. Las primeras semanas hay trabajos semanales, son cortos y sencillos y en las últimas semanas los proyectos donde hay que esforzarse un poco pero son proyectos completamente logrables.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6c411a45acd41ff4364822a68f1e2d99092ee1f6af9a0439f1c0c84c66862c46'::TEXT, ARRAY[1030]::BIGINT[]),
    (304::BIGINT, 'Elementos es un curso de programación de nivel BÁSICO.Si usted apenas está empezando o no conoce nada al respecto, considero que el profesor es muy buena opción.En cambio si usted ya tiene conociminento, lo van a penalizar sin motivo y va a ser un curso de relleno que igual va a requerir su atención'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '17fe304e5f5c0bc70fc746944f29e796e441c9fb0f3a609be14df943c259a3b9'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Hace el curso muy fácil aunque le tengas poco interes a la materia (como yo), normalmete solo hay que copiar el código que él hace en el laboratorio y enviarlo. No hace quices, para los exámenes da tiempo desde 1 hasta 3 semanas para entregarlos. Se pasa muy fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'da99a8977b3049dcdc8deb6198453df705600950f07e175b6daba6cfc729b25e'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Posiblemente el mejor profe para este curso, explica todas las veces que sea necesario, el curso se vuelve muy fácil con él y uno sí aprendé bastante, solo es de mostrar interés por el curso. Deja laboratorios todas las semanas pero son super sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-09-03T00:00:00+00:00'::TIMESTAMPTZ, '45b96f99a791acca07a2edf871c9da1cf7ea9e3bd60402028f368ed651c59236'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'El mejor profesor de elementos, dicen que no se aprende con él y que es "fácil" pero el sí enseña, desde cero, deja labs cada semana pero no son nada del otro mundo y además ayudan a repasar los temas, repite las veces que sea necesario, los exámenes son sencillos y deja buen tiempo para entregarlos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '716b7db970a4debe9e2d3b6cd3c97ccb710bb2aac3f0c6d719812c546f29ad30'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Buen profe, apasionado por enseñar. Entrega evaluaciones hasta fin del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b4472b48f2edc72a3253ac14a65f56112b351aae10c6668a472dd02776bbd037'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'El profe enseña muy bien y si alguien no entiende algo lo repite hasta que entiendan todos, deja muchas tareas pero por lo general son bastantes fáciles, los exámenes también.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes']::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, '34b15717988357e43d17cd34223363a37a5035b8e60b22f99debdfcdddd84531'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Excelente profesor. Su pedagogía para enseñar la materia es muy buena, sabe explicar de manera muy clara para las personas que nunca han tenido contacto con la programación, va explicando lento por lo que uno termina entendiendo y las clases no son aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-08T00:00:00+00:00'::TIMESTAMPTZ, '8a9440faedc6f299eeb4b61f62d66e50ca90cd8eacb024781773fd8c254a8119'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Explica muy bien, los laboratorios que pide usualmente se hacen en la clase o hace algunos como referencia, las tareas también. Para los parciales los hace principalmente prácticos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5a33926d3ba1f6607da44763a07ecfd1369201f30e041b0f93826ed5ca856a17'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'El mejor profe de verdad, muy divertido, los trabajos son sumamente sencillos a comparación con otros profes de la escuela de computación, se queda con vos hasta que entiendas las cosas, mis amigos se quedaron con otros profes en el curso y solicitaron repetir el curso con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'fe4d24bb0fa6997382002c33c87917760015bb5d940a4b50baa77257a4764bb4'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Es el mejor profe para llevar elementos, es muy amable, las clases son divertidas y explica muy bien, legalmente si puede matricular con el, hágalo de una.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e8af69c41dd996a616033d43ee711f97ed8d00e4c3adafc9a916d1c465c199ce'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'El profe la verdad explica muy bien, me gustó mucho la forma en la que desarrollaba la clase y nos dejaba trabajos que en realidad ayudaban montones a ir al día y entender los temas. Súper recomendado:)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6c8648d6b8f573ef5c4058ec1f347ac6e54c1764c9975db0a34b89252a41f6c9'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'Es muy buena gente, le importa que usted aprenda, deja laboratorios con ejercicios todas las semanas pero en la clase resuelve varios y así usted sabe más o menos cómo resolverlos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-10-28T00:00:00+00:00'::TIMESTAMPTZ, '13dcc40032533ea1f6a2df622a3f0056c8f8446b7dac3730ffbc71e8c0d6daa5'::TEXT, ARRAY[1249]::BIGINT[]),
    (304::BIGINT, 'ES demasiado bueno, deja mucha tarea pero el la ayuda a resolver en clases, no trate de copiar en los examenes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '50'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '384156666b89998c4064c6ee046b12b8e49024e94de85da418b941ed7f6c7ef1'::TEXT, ARRAY[1249]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
